// Expect input JSON: { user_input: string, session_memory?: object }
// Output: { router: { needs, timeParams, plan, notes } }
const input = items[0]?.json || {};
const text = (input.user_input || "").trim();
const sessionMemory = input.session_memory || {};

function isoNowTaipei() {
  const d = new Date();
  const pad = n => String(n).padStart(2,'0');
  // +08:00 fixed offset (Asia/Taipei)
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}+08:00`;
}

function parseDateRange(t) {
  const lower = t.toLowerCase();
  if (/(today|今天)/.test(lower)) return 'today';
  if (/(yesterday|昨天)/.test(lower)) return 'yesterday';
  if (/(last\\s*7\\s*days|近\\s*7\\s*天|過去7天)/.test(lower)) return 'last_7_days';
  if (/(this\\s*month|本月|這個月)/.test(lower)) return 'this_month';
  if (/(last\\s*month|上個月|上月)/.test(lower)) return 'last_month';
  return sessionMemory.default_date_range || 'today';
}

function detectNeeds(t) {
  const lower = t.toLowerCase();
  return {
    needChart: /(chart|圖表|折線|長條|圓餅|畫圖)/.test(lower),
    needSortOrGroup: /(group\\s*by|排序|排名|分組|聚合|總和|平均|百分位|中位數|前|top\\s*\\d+)/.test(lower),
    simpleCalc: /(加總|總和|ratio|比例|%|百分比|平均|差|\\+|\\-|\\*|\\/|=)/.test(lower) && !/(回歸|預測|模型)/.test(lower),
    mustSQL: /(\\bsql\\b|資料庫|join|多表|視窗函數|cte)/.test(lower),
  };
}

const needs = detectNeeds(text);
const dateRange = parseDateRange(text);
const timeParams = { now: isoNowTaipei(), date_range: dateRange };

const plan = [];
plan.push({ step: "A1_MCP", reason: "預設先用 MCP 取數", params: { timeParams } });
if (needs.needSortOrGroup) plan.push({ step: "A3_JSONALYZE", reason: "需要在 JSON 上進行 group/sort/聚合", params: {} });
if (needs.simpleCalc)      plan.push({ step: "A4_CALC",      reason: "偵測到簡易計算", params: {} });
if (needs.needChart)       plan.push({ step: "A5_CHART",     reason: "使用者要求圖表（資料源限定 MCP→JSONalyze）", params: { typeHint: "auto" } });
if (needs.mustSQL)         plan.push({ step: "A2_SQL",       reason: "明講需要 SQL 或疑似 DB 聚合/join", params: { timeParams } });

return [{ json: { router: { needs, timeParams, plan, notes: "Chart 只吃 MCP→(A3) 結果；MCP 無資料才退回 SQL。" }, user_input: text } }];

// Input optional: { calc: { expr: "(a-b)/b", vars: {a:120, b:100} } }
const ctx = items[0].json;
const req = ctx.calc || null;
function safeEval(expr, vars) {
  if (!expr) return null;
  if (!/^[0-9+\-*/().%\s_a-zA-Z]+$/.test(expr)) throw new Error('Bad expr');
  const keys = Object.keys(vars || {});
  const vals = keys.map(k => Number(vars[k]));
  const fn = new Function(...keys, `return ${expr};`);
  return fn(...vals);
}
let result = null;
if (req?.expr) result = safeEval(req.expr, req.vars || {});
return [{ json: { ...ctx, calc_result: result } }];

// Generate a minimal SQL when MCP reports no_data or mustSQL is true
// Expect input: { router, user_input, mcp_status? }
const j = items[0].json;
const dateRange = j.router?.timeParams?.date_range || 'this_month';
const where = (dateRange==='today') ? "date = CURRENT_DATE" :
              (dateRange==='this_month') ? "date >= date_trunc('month', CURRENT_DATE)" :
              (dateRange==='last_7_days') ? "date >= CURRENT_DATE - INTERVAL '7 days'" :
              "1=1";
const sql = `SELECT date, brand, revenue
             FROM sales
             WHERE ${where}
             ORDER BY date DESC
             LIMIT 100`;
return [{ json: { sql, notes: "auto-generated (replace table/fields)", risk: "medium" } }];

// Compose final markdown-ish answer.
const j = items[0].json;
const tools = [];
if (j.meta?.source === 'MCP' || j.MCP) tools.push('MCP');
if (j.jsonalyze_result || j.transform) tools.push('JSONalyze');
if (j.calc_result !== undefined) tools.push('Calc');
if (j.chart?.url || j.chart_url) tools.push('Chart');
if (j.sql || j.sql_result) tools.push('SQL');

const md = [
  `### 回覆`,
  `- 來源工具：${tools.join(' + ') || '（未識別）'}`,
  j.summary || '（此處可填最終結論與重點）',
].join('\\n');

return [{ json: { reply: md, raw: j } }];

// Expect: { thumbs_up: true, user_id, user_input, plan, tools, fingerprint }
// Normalize query and produce record for Data Store
const j = items[0].json || {};
const norm = (s) => (s||'').toLowerCase()
  .replace(/[^\p{L}\p{N}\s]/gu,' ')
  .replace(/\s+/g,' ')
  .trim();
const rec = {
  user_id: j.user_id || 'unknown',
  query_norm: norm(j.user_input),
  fingerprint: j.fingerprint || {},
  plan: j.plan || [],
  tools: j.tools || {},
  success: j.thumbs_up ? 1 : 0,
  ts: new Date().toISOString()
};
const key = `fb:${rec.user_id}:${Buffer.from(rec.query_norm).toString('base64').slice(0,24)}`;
return [{ json: { key, value: rec } }];
